function minutesToSpread(root: TreeNode | null, start: number): number {
  const adj = new Map<number, number[]>();
  const link = (a: number, b: number) => {
    if (!adj.has(a)) adj.set(a, []);
    if (!adj.has(b)) adj.set(b, []);
    adj.get(a)!.push(b); adj.get(b)!.push(a);
  };
  const stack = root ? [root] : [];
  adj.set(root!.val, []);
  while (stack.length) {
    const n = stack.pop()!;
    for (const c of [n.left, n.right]) if (c) { link(n.val, c.val); stack.push(c); }
  }
  const seen = new Set([start]);
  let level = [start], minutes = -1;
  while (level.length) {
    minutes++;
    const next: number[] = [];
    for (const v of level) for (const w of adj.get(v)!) if (!seen.has(w)) { seen.add(w); next.push(w); }
    level = next;
  }
  return minutes;
}

