    def minutesToSpread(self, root: Optional[TreeNode], start: int) -> int:
        adj = defaultdict(list)
        adj[root.val]
        stack = [root]
        while stack:
            n = stack.pop()
            for c in (n.left, n.right):
                if c:
                    adj[n.val].append(c.val)
                    adj[c.val].append(n.val)
                    stack.append(c)
        seen, level, minutes = {start}, [start], -1
        while level:
            minutes += 1
            nxt = []
            for v in level:
                for w in adj[v]:
                    if w not in seen:
                        seen.add(w)
                        nxt.append(w)
            level = nxt
        return minutes

