function minutesToSpread(root: TreeNode | null, start: number): number {
  let best = 0;
  // returns [height in nodes, distance from this node to start or -1]
  const dfs = (n: TreeNode | null): [number, number] => {
    if (!n) return [0, -1];
    const [lh, ld] = dfs(n.left), [rh, rd] = dfs(n.right);
    if (n.val === start) { best = Math.max(best, lh, rh); return [0, 0]; }
    if (ld >= 0) { best = Math.max(best, ld + 1 + rh); return [0, ld + 1]; }
    if (rd >= 0) { best = Math.max(best, rd + 1 + lh); return [0, rd + 1]; }
    return [1 + Math.max(lh, rh), -1];
  };
  dfs(root);
  return best;
}

